      where d.mission_id = expected.id and d.catalog = 'drawdown';
    if not found then
      raise exception 'Drawdown credit correction refused: missing target %', expected.id using errcode = '55000';
    end if;
    actual_md5 := md5(coalesce(actual.credit_line, '') || chr(31) || coalesce(actual.about, '') || chr(31) || coalesce(actual.about_credit, '') || chr(31) || coalesce(actual.source_url, '') || chr(31) || coalesce(actual.license_name, '') || chr(31) || coalesce(actual.license_url, '') || chr(31) || coalesce(actual.doi, ''));
    if actual_md5 = expected.after_md5 then continue; end if;
    if actual_md5 <> expected.before_md5 then
      raise exception 'Drawdown credit correction refused: credit or source changed for %', expected.id using errcode = '55000';
    end if;
    before_prefix := 'Solution summary from Project Drawdown (' || actual.source_url || '), used with permission';
    after_prefix := 'Solution listed in Project Drawdown''s Explorer (' || actual.source_url || ')';
    if left(actual.credit_line, length(before_prefix)) <> before_prefix then
      raise exception 'Drawdown credit correction refused: unexpected credit prefix for %', expected.id using errcode = '55000';
    end if;
    update public.action_mission_details
      set credit_line = after_prefix || substr(actual.credit_line, length(before_prefix) + 1),
          about = null,
          about_credit = null,
          updated_at = now()
      where mission_id = expected.id;
    select md5(coalesce(d.credit_line, '') || chr(31) || coalesce(d.about, '') || chr(31) || coalesce(d.about_credit, '') || chr(31) || coalesce(d.source_url, '') || chr(31) || coalesce(d.license_name, '') || chr(31) || coalesce(d.license_url, '') || chr(31) || coalesce(d.doi, '')) into actual_md5 from public.action_mission_details d where d.mission_id = expected.id;
    if actual_md5 <> expected.after_md5 then
      raise exception 'Drawdown credit correction refused: resulting fingerprint differs for %', expected.id using errcode = '55000';
    end if;
  end loop;

  if exists (select 1 from public.action_mission_details d where d.catalog = 'drawdown'
      and (d.about is not null or d.about_credit is not null or position('used with permission' in lower(d.credit_line)) > 0)) then
    raise exception 'Drawdown credit correction refused: unexpected website content remains' using errcode = '55000';
  end if;

end
